#include <bits/stdc++.h>
using namespace std;

#define REP(i, n) for (int i = 0; i < int(n); i++)

using pii = pair<int, int>;
using State = pair<pii, pii>;

bool visited[801][801][9][6];
bool used[801][801];
int t[500];
int X[9], Y[9];
int n, cnt;

void init() {
    X[1] = 0;  Y[1] = 1;
    X[2] = 1;  Y[2] = 1;
    X[3] = 1;  Y[3] = 0;
    X[4] = 1;  Y[4] = -1;
    X[5] = 0;  Y[5] = -1;
    X[6] = -1; Y[6] = -1;
    X[7] = -1; Y[7] = 0;
    X[8] = -1; Y[8] = 1;
}

void bfs() {
    if (n == 0) return;

    vector<queue<State>> mq(n);
    State start = {{400, 400}, {1, t[0]}};
    mq[0].push(start);
    visited[400][400][1][t[0]] = true;

    for (int i = 0; i < n; i++) {
        while (!mq[i].empty()) {
            State u = mq[i].front();
            mq[i].pop();

            int x = u.first.first;
            int y = u.first.second;
            int dir = u.second.first;
            int remaining = u.second.second;

            if (!used[x][y]) {
                used[x][y] = true;
                cnt++;
            }

            if (remaining == 1 && i + 1 < n) {
                int dirs[2] = {
                    (dir - 2 + 8) % 8 + 1,
                    dir % 8 + 1
                };

                for (int newDir : dirs) {
                    int nx = x + X[newDir];
                    int ny = y + Y[newDir];

                    if (!visited[nx][ny][newDir][t[i + 1]]) {
                        visited[nx][ny][newDir][t[i + 1]] = true;
                        mq[i + 1].push({{nx, ny}, {newDir, t[i + 1]}});
                    }
                }
            } else if (remaining > 1) {
                int nx = x + X[dir];
                int ny = y + Y[dir];

                if (!visited[nx][ny][dir][remaining - 1]) {
                    visited[nx][ny][dir][remaining - 1] = true;
                    mq[i].push({{nx, ny}, {dir, remaining - 1}});
                }
            }
        }
    }
}

int main() {
    init();
    scanf("%d", &n);
    REP(i, n) scanf("%d", &t[i]);
    bfs();
    printf("%d\n", cnt);
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

struct State {
    int x, y, dir, rem;

    bool operator==(const State& other) const {
        return x == other.x && y == other.y &&
               dir == other.dir && rem == other.rem;
    }
};

struct StateHash {
    size_t operator()(const State& s) const {
        size_t h = hash<int>()(s.x);
        h ^= hash<int>()(s.y) + 0x9e3779b9 + (h << 6) + (h >> 2);
        h ^= hash<int>()(s.dir) + 0x9e3779b9 + (h << 6) + (h >> 2);
        h ^= hash<int>()(s.rem) + 0x9e3779b9 + (h << 6) + (h >> 2);
        return h;
    }
};

struct Point {
    int x, y;

    bool operator==(const Point& other) const {
        return x == other.x && y == other.y;
    }
};

struct PointHash {
    size_t operator()(const Point& p) const {
        size_t h = hash<int>()(p.x);
        h ^= hash<int>()(p.y) + 0x9e3779b9 + (h << 6) + (h >> 2);
        return h;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    vector<int> t(n);
    for (int& value : t) cin >> value;

    if (n == 0) {
        cout << 0 << '\n';
        return 0;
    }

    const int dx[9] = {0, 0, 1, 1, 1, 0, -1, -1, -1};
    const int dy[9] = {0, 1, 1, 0, -1, -1, -1, 0, 1};

    queue<State> current;
    unordered_set<State, StateHash> currentSeen;
    unordered_set<Point, PointHash> used;

    State initial = {0, 0, 1, t[0]};
    current.push(initial);
    currentSeen.insert(initial);

    for (int i = 0; i < n; ++i) {
        queue<State> next;
        unordered_set<State, StateHash> nextSeen;

        while (!current.empty()) {
            State u = current.front();
            current.pop();

            used.insert({u.x, u.y});

            if (u.rem > 1) {
                State v = {
                    u.x + dx[u.dir],
                    u.y + dy[u.dir],
                    u.dir,
                    u.rem - 1
                };

                if (currentSeen.insert(v).second)
                    current.push(v);
            } else if (i + 1 < n) {
                int dir1 = (u.dir + 6) % 8 + 1;
                int dir2 = u.dir % 8 + 1;

                State v1 = {
                    u.x + dx[dir1],
                    u.y + dy[dir1],
                    dir1,
                    t[i + 1]
                };
                State v2 = {
                    u.x + dx[dir2],
                    u.y + dy[dir2],
                    dir2,
                    t[i + 1]
                };

                if (nextSeen.insert(v1).second)
                    next.push(v1);
                if (nextSeen.insert(v2).second)
                    next.push(v2);
            }
        }

        current = move(next);
        currentSeen = move(nextSeen);
    }

    cout << used.size() << '\n';
    return 0;
}

